window.VF1_UNITS = {"5":{"unit":5,"code":"VF1-U05","title":"Buying & Selling","startNumber":104,"endNumber":133,"entries":[{"number":104,"term":"advertise · advertisement · advert/ad","sourceTerm":"advertise (v) · advertisement (n) · advert/ad","spoken":"advertise · advertisement · advert or ad","ipa":"/ˈædvɚˌtaɪz æˈdvɝːtəzmənt ˈædvɚt ɔːr æd/","type":"verb · noun","meaning":"quảng cáo · bài hoặc mẩu quảng cáo · quảng cáo dạng viết tắt","definition":"To promote a product or service; a public notice that promotes it.","note":"","example":"The shop advertises its new bag online, and the advertisement also appears as a short ad."},{"number":105,"term":"afford st/to do st · affordable","sourceTerm":"afford st/to do st · affordable (a)","spoken":"afford something or to do something · affordable","ipa":"/əˈfɔːrd ˈsʌmθɪŋ ɔːr tuː duː ˈsʌmθɪŋ əˈfɔːrdəbəl/","type":"adjective","meaning":"đủ tiền chi trả cho điều gì hoặc để làm gì · có giá phải chăng, có thể chi trả được","definition":"To have enough money for something; not too expensive.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: afford st/to do st · affordable (a)","example":"My family can afford the course because the fee is affordable."},{"number":106,"term":"bargain","sourceTerm":"bargain (v) · (n)","spoken":"bargain","ipa":"/ˈbɑːrɡən/","type":"verb · noun","meaning":"mặc cả · món hời","definition":"To discuss a lower price; something sold for a very good price.","note":"Học theo nhóm từ/cụm và phân biệt đúng từ loại. Cách kết hợp: bargain (v) · (n)","example":"The jacket was a good bargain, and my mother bargained with the seller."},{"number":107,"term":"change","sourceTerm":"change (n)","spoken":"change","ipa":"/tʃeɪndʒ/","type":"noun","meaning":"tiền thừa, tiền thối lại","definition":"Money returned after someone pays more than the exact price.","note":"","example":"I paid with a large note and received the correct change."},{"number":108,"term":"debt · in debt (to sb)","sourceTerm":"debt (n) · in debt (to sb)","spoken":"debt · in debt to somebody","ipa":"/dɛt ɪn dɛt tuː ˈsʌˌmbɑːdi/","type":"noun","meaning":"món nợ · mắc nợ ai","definition":"Money that must be paid back; owing money.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: debt (n) · in debt (to sb)","example":"Lan borrowed too much money and is now in debt to her sister."},{"number":109,"term":"demand","sourceTerm":"demand (v,n)","spoken":"demand","ipa":"/dɪˈmænd/","type":"verb · noun","meaning":"yêu cầu, đòi hỏi · nhu cầu","definition":"To need or request; the amount that people want to buy.","note":"","example":"Demand for school uniforms rises before the new term."},{"number":110,"term":"supply","sourceTerm":"supply (v,n)","spoken":"supply","ipa":"/səˈplaɪ/","type":"verb · noun","meaning":"cung cấp · nguồn cung","definition":"To provide; the amount of something available.","note":"","example":"The school has a good supply of notebooks for all students."},{"number":111,"term":"import >< export","sourceTerm":"import (v,n) >< export (v,n)","spoken":"import >< export","ipa":"v /ɪmˈpɔːrt/ · n /ˈɪmpɔːrt/ >< v /ɪkˈspɔːrt/ · n /ˈɛkspɔːrt/","type":"verb · noun","meaning":"nhập khẩu; hàng nhập khẩu >< xuất khẩu; hàng xuất khẩu","definition":"To bring goods into a country, or goods brought in; to send goods to another country, or goods sent out.","note":"import và export đều dùng được như động từ và danh từ; trọng âm thay đổi theo từ loại.","example":"Vietnam imports some machines and exports many farm products; both imports and exports affect the economy."},{"number":112,"term":"fee · tuition fee · entrance fee/admission fee","sourceTerm":"fee (n) · tuition fee · entrance fee/admission fee","spoken":"fee · tuition fee · entrance fee or admission fee","ipa":"/fiː tjuˈɪʃən fiː ˈɛntrəns fiː ɔːr æˈdmɪʃən fiː/","type":"noun","meaning":"khoản phí · học phí · phí vào cửa","definition":"Money paid for a service, course, or admission.","note":"","example":"The tuition fee includes books, but the entrance fee is paid separately."},{"number":113,"term":"fortune · make a fortune","sourceTerm":"fortune (n) · make a fortune","spoken":"fortune · make a fortune","ipa":"/ˈfɔːrtʃən meɪk ə ˈfɔːrtʃən/","type":"noun","meaning":"vận may; tài sản lớn · kiếm được rất nhiều tiền","definition":"Luck or great wealth; to earn a large amount of money.","note":"","example":"The inventor made a fortune after many people bought her product."},{"number":114,"term":"invest in st · investment","sourceTerm":"invest (v) in st · investment (n)","spoken":"invest in something · investment","ipa":"/ˌɪˈnvɛst ɪn ˈsʌmθɪŋ ˌɪˈnvɛstmənt/","type":"verb · noun","meaning":"đầu tư vào điều gì · sự hoặc khoản đầu tư","definition":"To put money or resources into something for future benefit.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: invest (v) in st · investment (n)","example":"The school invested in new computers, and the investment helped students learn."},{"number":115,"term":"obtain ~ gain","sourceTerm":"obtain (v) ~ gain (v)","spoken":"obtain ~ gain","ipa":"/əˈbteɪn ɡeɪn/","type":"verb","meaning":"đạt được, thu được","definition":"To get or gain something.","note":"obtain nghĩa là có được, khá trang trọng; gain thường là đạt được dần dần hoặc nhận thêm lợi ích/kinh nghiệm.","example":"Students can obtain information and gain useful skills from the course."},{"number":116,"term":"owe sb st / st to sb","sourceTerm":"owe (v) sb st / st to sb","spoken":"owe somebody something or something to somebody","ipa":"/oʊ ˈsʌˌmbɑːdi ˈsʌmθɪŋ ɔːr ˈsʌmθɪŋ tuː ˈsʌˌmbɑːdi/","type":"verb","meaning":"nợ ai đó cái gì","definition":"To need to pay or return something to someone.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: owe (v) sb st / st to sb","example":"I owe my friend some money because she paid for my ticket."},{"number":117,"term":"own ~ possess","sourceTerm":"own (v) ~ possess (v)","spoken":"own ~ possess","ipa":"/oʊn pəˈzɛs/","type":"verb","meaning":"sở hữu","definition":"To have something as your property.","note":"own nhấn mạnh quyền sở hữu; possess trang trọng hơn và còn dùng cho phẩm chất/kĩ năng.","example":"My aunt owns the shop and possesses all the equipment inside it."},{"number":118,"term":"profit · profitable · make a profit from st","sourceTerm":"profit (v,n) · profitable (a) · make a profit from st","spoken":"profit · profitable · make a profit from something","ipa":"/ˈprɑːfət ˈprɑːfətəbəl meɪk ə ˈprɑːfət frʌm ˈsʌmθɪŋ/","type":"verb · noun · adjective","meaning":"kiếm lợi; lợi nhuận · có lợi nhuận, sinh lời · kiếm lời từ điều gì","definition":"To gain money; money remaining after costs; producing financial gain.","note":"profit dùng được như động từ và danh từ; profitable là tính từ.","example":"The shop profited from its new service and made a small profit because the service was profitable."},{"number":119,"term":"property","sourceTerm":"property (n)","spoken":"property","ipa":"/ˈprɑːpɚti/","type":"noun","meaning":"tài sản","definition":"Something owned by a person.","note":"","example":"This computer is school property, so students must use it carefully."},{"number":120,"term":"purchase ~ buy","sourceTerm":"purchase (v) ~ buy (v)","spoken":"purchase ~ buy","ipa":"/ˈpɝːtʃəs baɪ/","type":"verb","meaning":"mua","definition":"To buy something.","note":"purchase trang trọng hơn buy, thường gặp trong văn bản thương mại.","example":"The school purchased new books after deciding what to buy."},{"number":121,"term":"require · requirement","sourceTerm":"require (v) · requirement (n)","spoken":"require · requirement","ipa":"/ˌriˈkwaɪɚ rɪˈkwaɪrmənt/","type":"verb · noun","meaning":"yêu cầu, đòi hỏi · yêu cầu, điều kiện cần","definition":"To need or demand; something that is needed.","note":"","example":"The course requires regular practice, and this is its main requirement."},{"number":122,"term":"vary · a variety of ~ a lot of","sourceTerm":"vary (v) · a variety of ~ a lot of","spoken":"vary · a variety of ~ a lot of","ipa":"/ˈvɛri ə vɚˈaɪəti ʌv ə lɑːt ʌv/","type":"verb","meaning":"thay đổi, khác nhau · nhiều, đa dạng","definition":"To be different; many different types.","note":"vary là động từ 'thay đổi/khác nhau'; a variety of nghĩa là nhiều loại; a lot of chỉ số lượng nhiều, không nhất thiết đa dạng.","example":"Prices vary between shops, so buyers should look at a variety of choices."},{"number":123,"term":"by credit card · in cash","sourceTerm":"by credit card · in cash","spoken":"by credit card · in cash","ipa":"/baɪ ˈkrɛdət kɑːrd ɪn kæʃ/","type":"phrase / pattern","meaning":"bằng thẻ tín dụng · bằng tiền mặt","definition":"Using a payment card; using notes and coins.","note":"","example":"You can pay by credit card or in cash."},{"number":124,"term":"expense · living expense · expensive","sourceTerm":"expense (n) · living expense · expensive (a)","spoken":"expense · living expense · expensive","ipa":"/ɪˈkspɛns ˈlɪvɪŋ ɪˈkspɛns ɪˈkspɛnsɪv/","type":"noun · adjective","meaning":"chi phí · chi phí sinh hoạt · đắt, tốn nhiều tiền","definition":"Money spent; daily costs; costing a lot of money.","note":"","example":"Rent is a major living expense, and city homes can be expensive."},{"number":125,"term":"judge · judgement","sourceTerm":"judge (v) · judgement (n)","spoken":"judge · judgement","ipa":"/dʒʌdʒ ˈdʒʌdʒmənt/","type":"verb · noun","meaning":"đánh giá, phán xét · sự đánh giá, phán đoán","definition":"To form an opinion about quality or value; an opinion or decision.","note":"","example":"Do not judge a product by its colour; use careful judgement before buying it."},{"number":126,"term":"value · valuable ~ invaluable >< worthless","sourceTerm":"value (v,n) · valuable (a) ~ invaluable (a) >< worthless (a)","spoken":"value · valuable ~ invaluable >< worthless","ipa":"/ˈvælju ˈvæljəbəl ˌɪˈnvæljəbəl ˈwɝːθləs/","type":"verb · noun · adjective","meaning":"coi trọng; giá trị · có giá trị ~ vô cùng quý giá >< không có giá trị","definition":"To consider something important; importance or worth; worth a lot; extremely useful; having no value.","note":"value dùng được như động từ và danh từ. invaluable nghĩa là vô cùng quý giá; trái nghĩa là worthless.","example":"The school values practical experience; its most valuable advice is invaluable to new teachers, while outdated data may be worthless."},{"number":127,"term":"borrow st from sb · lend st to sb","sourceTerm":"borrow st from sb · lend st to sb","spoken":"borrow something from somebody · lend something to somebody","ipa":"/ˈbɑːˌroʊ ˈsʌmθɪŋ frʌm ˈsʌˌmbɑːdi lɛnd ˈsʌmθɪŋ tuː ˈsʌˌmbɑːdi/","type":"phrase / pattern","meaning":"mượn điều gì từ ai · cho ai mượn điều gì","definition":"To take and later return; to give for temporary use.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: borrow st from sb · lend st to sb","example":"I borrowed a book from Lan, and she lent it to me for a week."},{"number":128,"term":"serve · service","sourceTerm":"serve (v) · service (n)","spoken":"serve · service","ipa":"/sɝːv ˈsɝːvəs/","type":"verb · noun","meaning":"phục vụ · dịch vụ, sự phục vụ","definition":"To provide food or help; work done for a customer.","note":"","example":"The café serves healthy food and gives friendly service."},{"number":129,"term":"compare · comparison · compared to/with · in comparison to/with","sourceTerm":"compare (v) · comparison (n) · compared to/with · in comparison to/with","spoken":"compare · comparison · compared to or with · in comparison to or with","ipa":"/kəˈmpɛr kəˈmpɛrəsən kəˈmpɛrd tuː ɔːr wɪð ɪn kəˈmpɛrəsən tuː ɔːr wɪð/","type":"verb · noun","meaning":"so sánh · sự so sánh · so với · so với, xét trong tương quan với","definition":"To examine similarities and differences; the act of comparing.","note":"compare là động từ; compared to/with mở đầu phép so sánh; in comparison to/with là cụm nối mang tính học thuật.","example":"We compared two phones. In comparison with the first, the second was cheaper, and the comparison helped us choose."},{"number":130,"term":"wrong with # wrong about","sourceTerm":"wrong with # wrong about","spoken":"wrong with # wrong about","ipa":"/rɔːŋ wɪð rɔːŋ əˈbaʊt/","type":"phrase / pattern","meaning":"có vấn đề với… / bị làm sao · sai, nhầm về…","definition":"Not correct or not working; mistaken about a fact.","note":"wrong with nghĩa là có vấn đề/lỗi với ai hoặc vật; wrong about nghĩa là hiểu/đánh giá sai một thông tin.","example":"Something is wrong with the bill, and I think the shop is wrong about the total."},{"number":131,"term":"cost","sourceTerm":"cost (v,n)","spoken":"cost","ipa":"/kɑːst/","type":"verb · noun","meaning":"có giá, trị giá · chi phí; giá","definition":"To have a particular price; the amount paid for something.","note":"cost dùng được như động từ và danh từ.","example":"The course costs two million đồng, and the total cost includes all learning materials."},{"number":132,"term":"decide to V · decision · make a decision","sourceTerm":"decide (v) to V · decision (n) · make a decision","spoken":"decide to verb · decision · make a decision","ipa":"/ˌdɪˈsaɪd tuː vɝːb dɪˈsɪʒən meɪk ə dɪˈsɪʒən/","type":"verb · noun","meaning":"quyết định làm gì · quyết định · đưa ra quyết định","definition":"To choose an action; a choice that has been made.","note":"","example":"We decided to wait, and that decision saved money."},{"number":133,"term":"on ~ about · decide on st · agree on st","sourceTerm":"on ~ about · decide on st · agree on st","spoken":"on ~ about · decide on something · agree on something","ipa":"/ɑːn əˈbaʊt ˌdɪˈsaɪd ɑːn ˈsʌmθɪŋ əˈɡriː ɑːn ˈsʌmθɪŋ/","type":"phrase / pattern","meaning":"về điều gì · quyết định, lựa chọn điều gì · thống nhất, đồng ý về điều gì","definition":"Used with verbs such as decide and agree to identify the subject.","note":"decide on nghĩa là chọn sau khi cân nhắc; agree on nghĩa là cùng thống nhất về một việc; about chỉ chủ đề được nói đến.","example":"The group talked about the price, decided on a budget, and agreed on the final plan."}],"pronunciationFocus":[{"entryNumber":104,"points":[{"category":"word-stress","note":"advertise nhấn âm đầu; advertisement chuyển trọng âm sang âm tiết thứ hai"},{"category":"final-sound","note":"advertise kết thúc bằng /z/, không phải /s/"}]},{"entryNumber":108,"points":[{"category":"silent-letter","note":"Chữ b trong debt không được phát âm"},{"category":"final-sound","note":"debt kết thúc trực tiếp bằng /t/"}]},{"entryNumber":111,"points":[{"category":"word-stress","note":"import và export nhấn âm cuối khi là động từ, nhưng nhấn âm đầu khi là danh từ"}]},{"entryNumber":112,"points":[{"category":"word-stress","note":"tuition nhấn vào /ˈɪ/, còn admission nhấn vào /ˈmɪ/"}]},{"entryNumber":124,"points":[{"category":"final-sound","note":"expense kết thúc bằng /ns/; expensive giữ /s/ trước phần /ɪv/"}]},{"entryNumber":125,"points":[{"category":"common-error","note":"judge có một âm phụ cuối /dʒ/; không tách chữ d và g thành hai âm"},{"category":"final-sound","note":"Giữ trọn âm /dʒ/ ở cuối judge"}]},{"entryNumber":133,"points":[{"category":"linking","note":"Trong decide‿on, nối /d/ cuối decide sang nguyên âm /ɑː/ của on"}]}]}};
